class Solution(object):
    def reverse(self, x):
        """
        :type x: int
        :rtype: int
        """
        neg = False     # remember if x is negative
        if x < 0:
            neg = True
            x = -x      # work with a positive number

        rev = 0
        while x != 0:
            pop = x % 10      # take the last digit from x
            rev = rev * 10 + pop     # push that digit to the end of rev
            x //= 10    # drop the last digit from x

        if neg:
            rev = -rev      # put the sign back

        if rev < -2**31 or rev > 2**31 - 1:
            return 0
        return rev

